import { FrostTolerance, PlantCategory, PlantSpecies, SunRequirement } from '../types/domain';

/**
 * Bundled offline NZ plant catalog (Phase 1 target: ~150–250 high-value species).
 *
 * Months are NZ (Southern Hemisphere) calendar months 1–12. `kc` is the FAO-56 style crop
 * coefficient used by the watering engine. Te Reo Māori names are included only where a
 * widely-used name exists; entries should be reviewed with a te reo speaker before release.
 */

/** Parses compact month ranges: '9-11,3' → [9,10,11,3]; wraps across the year ('11-2' → [11,12,1,2]). */
export function parseMonths(spec: string): number[] {
  if (!spec.trim()) return [];
  const out: number[] = [];
  for (const part of spec.split(',')) {
    const [a, b] = part.split('-').map((s) => Number(s.trim()));
    if (a === undefined || Number.isNaN(a)) continue;
    if (b === undefined || Number.isNaN(b)) {
      out.push(a);
      continue;
    }
    let m = a;
    for (let guard = 0; guard < 12; guard++) {
      out.push(m);
      if (m === b) break;
      m = m === 12 ? 1 : m + 1;
    }
  }
  return Array.from(new Set(out));
}

export function deriveWaterDemandLabel(
  category: PlantCategory,
  kc: number
): PlantSpecies['waterDemandLabel'] {
  if (category === 'NZ Native' && kc <= 0.45) return 'Drought-Tolerant Native';
  if (kc < 0.6) return 'Low';
  if (kc < 0.9) return 'Moderate';
  return 'High';
}

interface PlantRow {
  id: string;
  name: string;
  reo?: string;
  bot: string;
  cat: PlantCategory;
  sun: SunRequirement;
  kc: number;
  frost: FrostTolerance;
  wind: boolean;
  spacing: number;
  h: number;
  w: number;
  fam: string;
  comp?: string[];
  anti?: string[];
  sow?: string;
  plant?: string;
  prune?: string;
  harvest?: string;
  care: string;
  nppa?: string;
}

function build(row: PlantRow): PlantSpecies {
  return {
    id: row.id,
    commonName: row.name,
    teReoName: row.reo,
    botanicalName: row.bot,
    category: row.cat,
    sunRequirement: row.sun,
    kc: row.kc,
    waterDemandLabel: deriveWaterDemandLabel(row.cat, row.kc),
    frostTolerance: row.frost,
    coastalWindTolerant: row.wind,
    spacingCm: row.spacing,
    matureHeightCm: row.h,
    matureSpreadCm: row.w,
    rotationFamily: row.fam,
    companions: row.comp ?? [],
    antagonists: row.anti ?? [],
    sowMonths: parseMonths(row.sow ?? ''),
    plantMonths: parseMonths(row.plant ?? ''),
    pruneMonths: parseMonths(row.prune ?? ''),
    harvestMonths: parseMonths(row.harvest ?? ''),
    isNppaWeed: row.cat === 'NPPA Weed',
    nppaDisposalAdvice: row.nppa,
    careSummary: row.care
  };
}

