export const NZ_PLANT_CATALOG: PlantSpecies[] = [
  ...VEGETABLES,
  ...HERBS,
  ...FRUIT,
  ...NATIVES,
  ...ORNAMENTALS,
  ...PEST_PLANTS
].map(build);

export const PLANT_SPECIES_BY_ID: Record<string, PlantSpecies> = Object.fromEntries(
  NZ_PLANT_CATALOG.map((p) => [p.id, p])
);

export function searchPlantCatalog(query: string, category?: PlantCategory): PlantSpecies[] {
  const q = query
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
  return NZ_PLANT_CATALOG.filter((p) => {
    if (category && p.category !== category) return false;
    if (!q) return true;
    const haystack = [p.commonName, p.teReoName ?? '', p.botanicalName, p.rotationFamily]
      .join(' ')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase();
    return haystack.includes(q);
  });
}
